from __future__ import annotations

from functools import lru_cache

import networkx as nx
from shapely.geometry import Polygon

from evac_sim.envs.environment import Environment
from evac_sim.envs.utils import add_edges_with_flow_capacity


def _build_environment(name, complete_area, obstacles, waypoints, node_capacities, edges, specific_areas):
    G = nx.DiGraph()
    for node, static_capacity in node_capacities.items():
        G.add_node(node, risk=0.0, blocked=False, is_stairs=False, floor=0, node_capacity=static_capacity)

    add_edges_with_flow_capacity(G, edges)

    return Environment(
        name=name,
        graph=G,
        complete_area=complete_area,
        obstacles=obstacles,
        waypoints=waypoints,
        sources=[],
        targets=[],
        specific_areas=specific_areas,
    )

